function cleanDigits(val?: string | null): string {
  return (val || '').replace(/\D/g, '');
}

function formatCpf(val?: string | null): string {
  const d = cleanDigits(val).slice(0, 11);
  if (d.length <= 3) return d;
  if (d.length <= 6) return `${d.slice(0, 3)}.${d.slice(3)}`;
  if (d.length <= 9) return `${d.slice(0, 3)}.${d.slice(3, 6)}.${d.slice(6)}`;
  return `${d.slice(0, 3)}.${d.slice(3, 6)}.${d.slice(6, 9)}-${d.slice(9, 11)}`;
}

function formatPhone(val?: string | null): string {
  const d = cleanDigits(val).slice(0, 11);
  if (d.length <= 2) return d;
  if (d.length <= 6) return `(${d.slice(0, 2)}) ${d.slice(2)}`;
  if (d.length <= 10) return `(${d.slice(0, 2)}) ${d.slice(2, 6)}-${d.slice(6)}`;
  return `(${d.slice(0, 2)}) ${d.slice(2, 7)}-${d.slice(7, 11)}`;
}

function formatBirth(val?: string | null): string {
  if (!val) return '';
  const parts = val.trim().split('/');
  if (parts.length === 3 && parts[2].length === 4) {
    return `${parts[0].padStart(2, '0')}/${parts[1].padStart(2, '0')}/${parts[2]}`;
  }
  return val;
}

function mapModality(planStr: string) {
  const p = (planStr || '').toLowerCase();
  if (p.includes('kids')) {
    return { code: 'KIDS', name: 'Lessa Kids', front: '/cards/38.png', back: '/cards/39.png', price: 0 };
  }
  if (p.includes('inclusão') || p.includes('inclusao') || p.includes('tea') || p.includes('pcd') || p.includes('pdc')) {
    return { code: 'PCD_TEA', name: 'Lessa Inclusão - PCD e TEA', front: '/cards/35.png', back: '/cards/24.png', price: 0 };
  }
  if (p.includes('vitalício') || p.includes('vitalicio') || p.includes('60+')) {
    return { code: 'IDOSO_60', name: 'Lessa Vitalício 60+', front: '/cards/26.png', back: '/cards/39.png', price: 0 };
  }
  if (p.includes('student') || p.includes('estudante')) {
    const isAnual = p.includes('anual');
    const isDay = p.includes('day');
    return { code: 'ESTUDANTE', name: 'Lessa Student Pass', front: '/cards/6.png', back: '/cards/24.png', price: isDay ? 0 : (isAnual ? 22.5 : 25) };
  }
  if (p.includes('professor')) {
    const isAnual = p.includes('anual');
    const isDay = p.includes('day');
    return { code: 'PROFESSOR', name: 'Lessa Professor Pass', front: '/cards/3.png', back: '/cards/24.png', price: isDay ? 0 : (isAnual ? 22.5 : 25) };
  }
  if (p.includes('servidor')) {
    const isAnual = p.includes('anual');
    const isDay = p.includes('day');
    return { code: 'SERVIDOR', name: 'Lessa Servidor Pass', front: '/cards/10.png', back: '/cards/24.png', price: isDay ? 0 : (isAnual ? 22.5 : 25) };
  }
  if (p.includes('corporate')) {
    return { code: 'CORPORATE', name: 'Lessa Corporate Pass', front: '/cards/44.png', back: '/cards/24.png', price: 0 };
  }
  if (p.includes('parceiro')) {
    return { code: 'PARCEIRO', name: 'Lessa Parceiro', front: '/cards/21.png', back: '/cards/24.png', price: 39.9 };
  }
  if (p.includes('publicidade')) {
    return { code: 'ADULTO', name: 'Lessa Family Publicidade', front: '/cards/44.png', back: '/cards/24.png', price: 0 };
  }
  if (p.includes('duo')) {
    return { code: 'ADULTO', name: 'Lessa Duo Club', front: '/cards/44.png', back: '/cards/24.png', price: 74.9 };
  }

  // Default Lessa Club
  let price = 49.9;
  if (p.includes('2 pessoas') || p.includes('2')) price = 99.8;
  if (p.includes('3 pessoas') || p.includes('3')) price = 149.7;
  if (p.includes('4 pessoas') || p.includes('4')) price = 199.6;
  if (p.includes('5 pessoas') || p.includes('5')) price = 249.5;
  if (p.includes('1.077')) price = 89.82;
  if (p.includes('538')) price = 44.91;
  return { code: 'ADULTO', name: 'Lessa Club', front: '/cards/44.png', back: '/cards/24.png', price };
}

